<template><div class="form-page"><div class="form-wrap"><form class="form-card" @submit.prevent="submit"><img src="/logo.svg" style="width:155px;margin-bottom:24px"/><h1>Become a BraTips tipster</h1><p class="muted">Build a public track record, grow your followers and qualify for streak rewards.</p><div v-if="success" class="success">{{success}} <RouterLink to="/login" style="font-weight:800">Log in →</RouterLink></div><div v-if="error" class="error">{{error}}</div><template v-if="!success"><div class="grid2"><div class="field"><label>Name</label><input v-model="f.name" required/></div><div class="field"><label>Username</label><input v-model="f.username" required minlength="3"/></div></div><div class="field"><label>Email</label><input v-model="f.email" type="email" required/></div><div class="field"><label>Password</label><input v-model="f.password" type="password" minlength="8" required/></div><div class="field"><label>Country</label><input v-model="f.country"/></div><div class="field"><label>Bio</label><textarea v-model="f.bio" minlength="20" required placeholder="Tell users what you specialize in…"/></div><div class="field"><label>Expertise</label><input v-model="expertise" placeholder="Premier League, goals, corners"/></div><h3>Sample prediction</h3><div class="field"><label>Fixture</label><input v-model="f.samplePrediction.fixture" required/></div><div class="grid2"><div class="field"><label>Prediction</label><input v-model="f.samplePrediction.prediction" required/></div><div class="field"><label>Odds</label><input v-model.number="f.samplePrediction.odds" type="number" step="0.01" min="1" required/></div></div><div class="field"><label>Analysis</label><textarea v-model="f.samplePrediction.analysis" minlength="20" required/></div><button class="btn">Submit for approval</button></template></form></div></div></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {RouterLink} from 'vue-router';import {useAuth} from '../stores/auth';const auth=useAuth(),error=ref(''),success=ref(''),expertise=ref('');const f=reactive<any>({name:'',username:'',email:'',password:'',country:'',bio:'',samplePrediction:{fixture:'',prediction:'',odds:1.5,analysis:''}});async function submit(){error.value='';try{const d=await auth.tipsterApply({...f,expertise:expertise.value.split(',').map(x=>x.trim()).filter(Boolean),samplePrediction:{...f.samplePrediction,confidence:80}});success.value=d.message}catch(e:any){error.value=e.message}}</script>
